//! Loading third-party plugins from shared libraries.
//!
//! A plugin ships a `plugin.ntp.kdl` manifest next to a shared library
//! built with the same toolchain and SDK as Notein. The library exports
//! the functions generated by [`export_plugin!`]:
//!
//! ```rust,ignore
//! notein_plugin::export_plugin!(Music::default());
//! ```

use std::path::{Path, PathBuf};
use std::sync::Arc;

use libloading::Library;
use notein_i18n::{Lang, tr};

use crate::create::CreationEntry;
use crate::failure::UserMessage;
use crate::info::PluginInfo;
use crate::kind::KindInfo;
use crate::manifest::{ManifestError, PluginManifest};
use crate::plugin::{Plugin, Registrar};
use crate::target::Target;

/// Version of the plugin contract. A plugin built against another one
/// is refused before any of its code runs past the entry function.
pub const SDK_ABI_VERSION: u32 = 2;

/// Name of the exported entry symbol.
pub const ENTRY_SYMBOL: &[u8] = b"notein_plugin_entry\0";

/// Name of the exported language setter. A library carries its own
/// copy of the interface-language global, so the host sets it there.
pub const LANG_SYMBOL: &[u8] = b"notein_plugin_set_lang\0";

/// What the entry function returns.
pub struct PluginExport {
    pub abi: u32,
    pub plugin: Arc<dyn Plugin>,
}

impl std::fmt::Debug for PluginExport {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PluginExport")
            .field("abi", &self.abi)
            .finish_non_exhaustive()
    }
}

/// Signature of the entry function.
pub type PluginEntryFn = fn() -> PluginExport;

/// Signature of the language setter.
pub type LangSetterFn = fn(Lang);

/// Export `$plugin` as this library's Notein plugin, along with the
/// setter the host calls to keep the plugin on its interface language.
#[macro_export]
macro_rules! export_plugin {
    ($plugin:expr) => {
        #[unsafe(no_mangle)]
        pub fn notein_plugin_entry() -> $crate::loader::PluginExport {
            $crate::loader::PluginExport {
                abi: $crate::loader::SDK_ABI_VERSION,
                plugin: ::std::sync::Arc::new($plugin),
            }
        }

        #[unsafe(no_mangle)]
        pub fn notein_plugin_set_lang(lang: $crate::i18n::Lang) {
            lang.make_current();
        }
    };
}

/// Why a plugin could not be loaded. Shown in Settings › Plugins.
#[derive(Debug)]
pub enum LoaderError {
    Manifest(ManifestError),
    MissingLibrary {
        manifest: PathBuf,
    },
    /// The manifest lists libraries, none for this device.
    NoLibraryForDevice {
        plugin: String,
        device: String,
        /// The platforms it does ship for.
        targets: Vec<String>,
    },
    Open {
        library: PathBuf,
        error: libloading::Error,
    },
    MissingEntry {
        library: PathBuf,
        error: libloading::Error,
    },
    AbiMismatch {
        plugin: String,
        expected: u32,
        found: u32,
    },
}

impl UserMessage for LoaderError {
    fn user_message(&self) -> String {
        match self {
            Self::Manifest(err) => err.user_message(),
            Self::MissingLibrary { .. } | Self::Open { .. } | Self::MissingEntry { .. } => {
                tr!("plugin-load-not-for-device")
            }
            Self::NoLibraryForDevice {
                plugin,
                device,
                targets,
            } => tr!(
                "plugin-load-no-library",
                "plugin" => plugin.as_str(),
                "device" => device.as_str(),
                "targets" => targets.join(", "),
            ),
            Self::AbiMismatch {
                plugin,
                expected,
                found,
            } if found > expected => {
                tr!("plugin-load-needs-newer-app", "plugin" => plugin.as_str())
            }
            Self::AbiMismatch { plugin, .. } => {
                tr!("plugin-load-built-for-older-app", "plugin" => plugin.as_str())
            }
        }
    }
}

impl std::fmt::Display for LoaderError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Manifest(e) => write!(f, "manifest: {e}"),
            Self::MissingLibrary { manifest } => {
                write!(f, "no library next to {}", manifest.display())
            }
            Self::NoLibraryForDevice {
                plugin,
                device,
                targets,
            } => write!(
                f,
                "{plugin}: no library for {device} (ships {})",
                targets.join(", ")
            ),
            Self::Open { library, error } => write!(f, "open {}: {error}", library.display()),
            Self::MissingEntry { library, error } => {
                write!(f, "entry in {}: {error}", library.display())
            }
            Self::AbiMismatch {
                plugin,
                expected,
                found,
            } => {
                write!(f, "{plugin}: SDK ABI v{found}, host expects v{expected}")
            }
        }
    }
}

impl std::error::Error for LoaderError {}

impl From<ManifestError> for LoaderError {
    fn from(err: ManifestError) -> Self {
        Self::Manifest(err)
    }
}

/// An open plugin library and the language setter it exports.
pub struct PluginLibrary {
    /// Resolved from `library`, so only valid while it stays open;
    /// `None` for a library built without it.
    set_lang: Option<LangSetterFn>,
    library: Library,
}

impl std::fmt::Debug for PluginLibrary {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PluginLibrary")
            .field("set_lang", &self.set_lang.is_some())
            .finish_non_exhaustive()
    }
}

impl PluginLibrary {
    /// Open `path` and resolve its language setter.
    ///
    /// # Safety
    /// Loading a library runs its initialisers with the app's
    /// privileges; `path` must be a plugin the user chose to install.
    unsafe fn open(path: &Path) -> Result<Self, libloading::Error> {
        // SAFETY: upheld by the caller (see above).
        let library = unsafe { Library::new(path) }?;
        // SAFETY: `notein_plugin_set_lang` is generated by
        // `export_plugin!` with exactly the `LangSetterFn` signature.
        // The copied pointer lives next to `library`, which keeps the
        // code it points to mapped.
        let set_lang = unsafe { library.get::<LangSetterFn>(LANG_SYMBOL) }
            .ok()
            .map(|symbol| *symbol);
        Ok(Self { set_lang, library })
    }

    /// Show the plugin's text in `lang` from now on.
    #[cfg_attr(feature = "sismo", sismo::function("plugin::loader_set_lang"))]
    pub fn set_lang(&self, lang: Lang) {
        if let Some(set_lang) = self.set_lang {
            set_lang(lang);
        }
    }
}

/// A plugin loaded from disk. Keep `library` alive for as long as any
/// object created by `plugin` (hand it to the catalog).
pub struct Loaded {
    pub manifest: PluginManifest,
    pub library_path: PathBuf,
    pub plugin: Arc<dyn Plugin>,
    pub library: PluginLibrary,
}

impl std::fmt::Debug for Loaded {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Loaded")
            .field("manifest", &self.manifest)
            .field("library_path", &self.library_path)
            .finish_non_exhaustive()
    }
}

/// What installing a plugin would add, for the review step.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Review {
    pub info: PluginInfo,
    pub kinds: Vec<KindInfo>,
    pub entries: Vec<CreationEntry>,
    pub settings: usize,
}

impl Loaded {
    /// Describe what the plugin contributes.
    #[must_use]
    #[cfg_attr(feature = "sismo", sismo::function("plugin::loader_review"))]
    pub fn review(&self) -> Review {
        let mut registrar = Registrar::default();
        self.plugin.register(&mut registrar);
        Review {
            info: self.plugin.info(),
            kinds: registrar.kinds.iter().map(|k| k.info()).collect(),
            entries: registrar
                .kinds
                .iter()
                .flat_map(|k| k.creation_entries())
                .collect(),
            settings: registrar.settings.map_or(0, |s| s.schema().fields.len()),
        }
    }
}

/// Load the plugin described by `manifest_path`.
///
/// # Errors
/// [`LoaderError`] when the manifest, the library or its entry are
/// missing or the plugin targets another SDK version.
#[cfg_attr(feature = "sismo", sismo::function("plugin::loader_load"))]
pub fn load(manifest_path: &Path) -> Result<Loaded, LoaderError> {
    let manifest = PluginManifest::from_path(manifest_path)?;
    let device = Target::current();
    let library_path = manifest
        .library_for(manifest_path, &device)
        .ok_or_else(|| {
            if manifest.libraries.is_empty() {
                LoaderError::MissingLibrary {
                    manifest: manifest_path.to_path_buf(),
                }
            } else {
                LoaderError::NoLibraryForDevice {
                    plugin: manifest.name.clone(),
                    device: device.to_string(),
                    targets: manifest.targets(),
                }
            }
        })?;
    // SAFETY: the user chose to install this plugin; the manifest and
    // ABI checks below reject anything not built for this SDK.
    let library =
        unsafe { PluginLibrary::open(&library_path) }.map_err(|error| LoaderError::Open {
            library: library_path.clone(),
            error,
        })?;
    // Before the entry runs, so text the plugin builds on creation
    // is already in the interface language.
    library.set_lang(Lang::current());
    let export = {
        // SAFETY: `notein_plugin_entry` is generated by `export_plugin!`
        // with exactly the `PluginEntryFn` signature; the symbol name is
        // only ever produced by that macro.
        let entry: libloading::Symbol<PluginEntryFn> = unsafe { library.library.get(ENTRY_SYMBOL) }
            .map_err(|error| LoaderError::MissingEntry {
                library: library_path.clone(),
                error,
            })?;
        entry()
    };
    if export.abi != SDK_ABI_VERSION {
        return Err(LoaderError::AbiMismatch {
            plugin: manifest.name,
            expected: SDK_ABI_VERSION,
            found: export.abi,
        });
    }
    Ok(Loaded {
        manifest,
        library_path,
        plugin: export.plugin,
        library,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    struct Blank;

    impl Plugin for Blank {
        fn info(&self) -> PluginInfo {
            PluginInfo::new("dev.blank", "Blank")
        }

        fn register(&self, _registrar: &mut Registrar) {}
    }

    // The macro emits `pub` items meant for a cdylib root.
    #[allow(unreachable_pub)]
    mod exported {
        crate::export_plugin!(super::Blank);
    }

    #[test]
    fn exported_symbols_match_the_loader_signatures() {
        let entry: PluginEntryFn = exported::notein_plugin_entry;
        let set_lang: LangSetterFn = exported::notein_plugin_set_lang;
        assert_eq!(entry().abi, SDK_ABI_VERSION);
        set_lang(Lang::Es);
        assert_eq!(Lang::current(), Lang::Es);
    }

    #[test]
    fn newer_abi_asks_to_update_the_app() {
        notein_i18n::Lang::Es.make_current();
        let err = LoaderError::AbiMismatch {
            plugin: "Partituras".to_owned(),
            expected: SDK_ABI_VERSION,
            found: SDK_ABI_VERSION + 1,
        };
        assert!(err.user_message().contains("más nueva"));
    }

    #[test]
    fn a_plugin_for_other_devices_says_which() {
        let err = LoaderError::NoLibraryForDevice {
            plugin: "Corán".to_owned(),
            device: "android-aarch64".to_owned(),
            targets: vec!["linux-x86_64".to_owned(), "macos".to_owned()],
        };
        let message = err.user_message();
        assert!(message.contains("android-aarch64"), "{message}");
        assert!(message.contains("linux-x86_64, macos"), "{message}");
    }
}
